content.text:
{
  "decision": "write",
  "essentials": [
    {
      "name": "Crazy House",
      "local_name": "Hằng Nga Guesthouse",
      "kind": "other",
      "area": null,
      "why": {
        "en": "Wander through a surreal, Gaudi-esque fantasy house with winding bridges, giant tree trunks and hidden caves.",
        "vi": "Dạo bước qua ngôi nhà siêu thực như trong truyện cổ tích với những cây cầu uốn lượn, thân cây khổng lồ và hang động ẩn giấu."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "A striking, not-quite-finished Gaudi-esque fantasy house designed by the daughter of an independence war hero."
    },
    {
      "name": "Xuan Huong Lake",
      "local_name": "Hồ Xuân Hương",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "Stroll the 5-km lakeside promenade in the city centre, rent a boat, and watch honeymooners and locals enjoy the scenery.",
        "vi": "Tản bộ dọc bờ hồ dài 5 km ngay trung tâm thành phố, thuê thuyền và ngắm nhìn khung cảnh lãng mạn."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "Now, Xuan Huong Lake is one of the main draws of Da Lat, and you can see honeymooners and locals strolling its banks."
    },
    {
      "name": "Dalat Market",
      "local_name": "Chợ Đà Lạt",
      "kind": "market",
      "area": null,
      "why": {
        "en": "Browse stalls of strawberry jam, artichokes, avocados and dried fruits, then try hot soy milk at the night market.",
        "vi": "Dạo quanh các gian hàng mứt dâu, atiso, bơ và trái cây sấy, rồi thưởng thức sữa đậu nành nóng ở chợ đêm."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "Filled with local specialities: strawberry jam, fruit conserves, avocado, artichokes."
    },
    {
      "name": "Truc Lam Zen Monastery",
      "local_name": "Thiền Viện Trúc Lâm",
      "kind": "temple_shrine",
      "area": null,
      "why": {
        "en": "Ride a cable car over pine forest to a peaceful monastery with landscaped gardens and views over the dams below.",
        "vi": "Đi cáp treo qua rừng thông đến ngôi thiền viện thanh bình với những khu vườn được cắt tỉa và tầm nhìn xuống hồ."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "The monastery has a magnificent view over the dams below and its gardens are full of landscaped shrubs in animal form."
    },
    {
      "name": "Linh Phuoc Pagoda",
      "local_name": "Chùa Linh Phước",
      "kind": "temple_shrine",
      "area": null,
      "why": {
        "en": "Admire a seven-level pagoda covered in intricate mosaics made from broken porcelain, unlike any other temple in Vietnam.",
        "vi": "Chiêm ngưỡng ngôi chùa bảy tầng được trang trí bằng những bức tranh khảm từ mảnh sứ vỡ, độc nhất vô nhị ở Việt Nam."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "Broken porcelain is used to compose beautiful mosaics that adorn the whole of this 7-level pagoda, and it is still expanding."
    },
    {
      "name": "Langbiang Mountain",
      "local_name": "Núi Langbiang",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "Hike or take a Jeep to the 1,915-m peak for panoramic views, or tackle the 2,167-m summit on a 2-3 hour trek.",
        "vi": "Đi bộ hoặc đi xe Jeep lên đỉnh cao 1.915 m để ngắm toàn cảnh, hoặc chinh phục đỉnh 2.167 m bằng chuyến leo núi 2-3 giờ."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "There are 2 peaks: 1915 m and 2167 m. First one is reachable by a steep paved path, you can ride in a Jeep (360,000 dong for 1 Jeep)."
    },
    {
      "name": "Valley of Love",
      "local_name": "Thung Lũng Tình Yêu",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "A romantic stop popular with honeymooners, with landscaped gardens and opportunities for canyoning.",
        "vi": "Điểm dừng chân lãng mạn được các cặp đôi yêu thích, với những khu vườn được chăm chút và cơ hội chơi canyoning."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "The Valley of Love is common stop on Dalat tours and is very popular with honeymooners."
    },
    {
      "name": "Tuyen Lam Lake",
      "local_name": "Hồ Tuyền Lâm",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "Relax by one of the largest and most beautiful lakes in town, with clean green waters and hiking on nearby Voi Mountain.",
        "vi": "Thư giãn bên một trong những hồ lớn và đẹp nhất thành phố, với làn nước xanh trong và cơ hội leo núi Voi gần đó."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "It is one of the largest and most beautiful lakes in town."
    },
    {
      "name": "Pongour Falls",
      "local_name": "Thác Pongour",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "See one of the largest and widest waterfalls in Vietnam, especially magnificent during the wet season.",
        "vi": "Chiêm ngưỡng một trong những thác nước lớn và rộng nhất Việt Nam, đặc biệt hùng vĩ vào mùa mưa."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "It's one of the largest and widest waterfalls in Vietnam and during the wet season is a magnificent sight."
    },
    {
      "name": "Datanla Waterfalls",
      "local_name": "Thác Datanla",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "Combine a waterfall visit with a fun alpine coaster ride through the forest.",
        "vi": "Kết hợp tham quan thác nước với trải nghiệm máng trượt vui nhộn xuyên qua rừng."
      },
      "source_url": "https://www.youtube.com/watch?v=Dk0aDYj0F7s",
      "quote": "Datanla Waterfalls & Coaster"
    },
    {
      "name": "Dalat Flower Park",
      "local_name": "Vườn hoa Đà Lạt",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "Wander through flower gardens centred around a reconstructed traditional Vietnamese teak wood house.",
        "vi": "Dạo bước qua những vườn hoa xoay quanh ngôi nhà gỗ lim truyền thống Việt Nam được phục dựng."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "A set of flower gardens centred around a reconstructed traditional Vietnamese teak wood house."
    },
    {
      "name": "Dalat Railway Station",
      "local_name": "Ga Đà Lạt",
      "kind": "other",
      "area": null,
      "why": {
        "en": "Visit a historic French colonial railway station, one of the top attractions in Da Lat.",
        "vi": "Ghé thăm nhà ga xe lửa cổ từ thời Pháp thuộc, một trong những điểm tham quan hàng đầu ở Đà Lạt."
      },
      "source_url": "https://www.youtube.com/watch?v=b-0W0xv2Ww0",
      "quote": "Dalat Railway Station 03:51"
    },
    {
      "name": "Nha Tho Domaine de Marie",
      "local_name": "Nhà thờ Domaine de Marie",
      "kind": "temple_shrine",
      "area": null,
      "why": {
        "en": "See a pink church on a hilltop and buy dried fruits and snacks from the nuns' store.",
        "vi": "Ngắm nhà thờ màu hồng trên đỉnh đồi và mua trái cây sấy cùng đồ ăn vặt từ cửa hàng của các nữ tu."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "A pink church on top of a hill, with a store selling various dried fruits and snacks from the local orchards run by the nuns of the monastery."
    },
    {
      "name": "Lake of Sorrow",
      "local_name": "Hồ Than Thở",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "Visit a lake named after a tragic love story, a common destination in Dalat.",
        "vi": "Ghé thăm hồ nước mang tên một câu chuyện tình buồn, điểm đến quen thuộc ở Đà Lạt."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "The Lake of Sorrow is a common destination in Dalat."
    },
    {
      "name": "Prenn Falls",
      "local_name": "Thác Prenn",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "A beautiful waterfall that is more fun when you hike it than just take pictures.",
        "vi": "Thác nước tuyệt đẹp, thú vị hơn khi bạn leo bộ thay vì chỉ chụp ảnh."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "Prenn Falls is quite beautiful, but is a lot more fun when you're hiking it than just taking pictures of it."
    },
    {
      "name": "Golden Spring Lake",
      "local_name": "Hồ Suối Vàng",
      "kind": "nature",
      "area": null,
      "why": {
        "en": "Enjoy unspoiled scenery at this lesser-known lake.",
        "vi": "Tận hưởng khung cảnh hoang sơ tại hồ nước ít người biết đến này."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "Golden Spring Lake (Ho Suoi Vang). Unspoiled scenery."
    }
  ],
  "eateries": [
    {
      "name": "Dalat Palace Golf Club",
      "local_name": null,
      "dish": null,
      "why": {
        "en": "Enjoy Mexican and Western food with a great view of the deep green fairways.",
        "vi": "Thưởng thức món Mexico và phương Tây với tầm nhìn tuyệt đẹp ra những thảm cỏ xanh mướt."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat",
      "quote": "The coffee shop at the golf course has some wholesome meals of Asian and European food, with great view of the deep green fairways and classy environment."
    },
    {
      "name": "Vcafe restaurant",
      "local_name": null,
      "dish": null,
      "why": {
        "en": "A popular place for Western travellers with a diverse international menu and live music every evening.",
        "vi": "Địa điểm quen thuộc của du khách phương Tây với thực đơn quốc tế đa dạng và nhạc sống mỗi tối."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Popular place for Western travellers. Diverse menu of international dishes and live music every evening."
    },
    {
      "name": "IndiaGate",
      "local_name": null,
      "dish": null,
      "why": {
        "en": "Indian restaurant with vegan and halal options available.",
        "vi": "Nhà hàng Ấn Độ có các lựa chọn thuần chay và halal."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Indian restaurant. Vegan and halal options available."
    },
    {
      "name": "Fungi Chingu Chợ Đêm",
      "local_name": null,
      "dish": null,
      "why": {
        "en": "Korean BBQ spot near the night market.",
        "vi": "Quán nướng Hàn Quốc gần chợ đêm."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Fungi Chingu Chợ Đêm - Quán nướng Hàn Quốc. Korean BBQ"
    },
    {
      "name": "Bánh Mì Xíu Mại Ri 79",
      "local_name": null,
      "dish": "Bánh mì xíu mại",
      "why": {
        "en": "A budget spot known for its bánh mì xíu mại.",
        "vi": "Quán bình dân nổi tiếng với món bánh mì xíu mại."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Bánh Mì Xíu Mại Ri 79."
    },
    {
      "name": "Bánh ướt lòng gà LONG",
      "local_name": null,
      "dish": "Bánh ướt lòng gà",
      "why": {
        "en": "A budget eatery serving bánh ướt lòng gà.",
        "vi": "Quán bình dân phục vụ món bánh ướt lòng gà."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Bánh ướt lòng gà LONG."
    },
    {
      "name": "Sữa đậu nành Nguyễn Văn Cừ",
      "local_name": null,
      "dish": "Sữa đậu nành",
      "why": {
        "en": "A soya milk stall, a local favourite.",
        "vi": "Quầy sữa đậu nành được người dân địa phương yêu thích."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Sữa đậu nành Nguyễn Văn Cừ -Soya Milk Stall."
    },
    {
      "name": "Cơm chay Thanh Đạm",
      "local_name": null,
      "dish": "Cơm chay",
      "why": {
        "en": "A vegetarian rice eatery in the budget category.",
        "vi": "Quán cơm chay bình dân."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Cơm chay Thanh Đạm."
    },
    {
      "name": "Quán Cơm chay An Lạc Tâm",
      "local_name": null,
      "dish": "Cơm chay",
      "why": {
        "en": "Another budget vegetarian rice option.",
        "vi": "Một lựa chọn cơm chay bình dân khác."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Quán Cơm chay An Lạc Tâm."
    },
    {
      "name": "Goc ha thanh",
      "local_name": null,
      "dish": null,
      "why": {
        "en": "A mid-range dining option in Da Lat.",
        "vi": "Một lựa chọn ăn uống tầm trung ở Đà Lạt."
      },
      "source_url": "https://en.wikivoyage.org/wiki/Da_Lat#Eat",
      "quote": "Goc ha thanh."
    }
  ],
  "stays": [
    {
      "tier": "budget",
      "low": 200000,
      "high": 350000,
      "currency": "VND",
      "source_url": "https://www.vietnamtourism.com/en/where-to-stay-in-da-lat-neighborhoods-and-hotel-picks-by-budget",
      "quote": "Budget guesthouses start at 200,000 VND ($8) per night, mid-range hotels run 500,000-1,200,000 VND ($20-48)"
    },
    {
      "tier": "mid",
      "low": 500000,
      "high": 1200000,
      "currency": "VND",
      "source_url": "https://www.vietnamtourism.com/en/where-to-stay-in-da-lat-neighborhoods-and-hotel-picks-by-budget",
      "quote": "Budget guesthouses start at 200,000 VND ($8) per night, mid-range hotels run 500,000-1,200,000 VND ($20-48)"
    },
    {
      "tier": "upscale",
      "low": 2500000,
      "high": 3500000,
      "currency": "VND",
      "source_url": "https://www.vietnamtourism.com/en/where-to-stay-in-da-lat-neighborhoods-and-hotel-picks-by-budget",
      "quote": "Rates start around 3,500,000 VND ($140) per night."
    }
  ]
}
